        next: [
          redirect({
            when: Session('patternSubmitted.pre-fill').match(Condition.Equals(true)),
            goto: 'confirmation',
          }),
        ],
      },
    }),
  ],
  sourceBase: 'pre-fill/demo/check-answers',
  codeFiles: ['step.ts', 'blocks.ts'],
})

