  .branch(Condition.Equals('search-engine'), 'Search engine')
  .branch(Condition.Equals('social-media'), 'Social media')
  .branch(Condition.Equals('friend-or-colleague'), 'Friend or colleague')
  .branch(Condition.Equals('other'), 'Other')
  .otherwise('')

